# V-01 (PR #1108 closing claim, upgrade path). Verifier's rebuild: the original counted only a rewrite or a
# NOTICE/WARNING naming localtime as the defect being absent; this one also accepts a pgpm.log row written by
# the upgrade or the tick that names localtime, so a fix that flags through the log is not read as the defect.
# A pre-fix install's _canonical_tz (the base's body, restored
# verbatim as the pre-upgrade state) lets set_partition_tz record 'localtime'. The tree under test's
# install.sql is then run over it, the documented upgrade. Defect present when the recorded zone is still
# 'localtime' afterwards and neither the upgrade install nor a maintenance tick said anything about it.
set -uo pipefail
q() { $PSQL -tA "$@"; }
fail=0
say() { if [ "$1" = ok ]; then echo "ok - $2"; else echo "not ok - $2"; fail=1; fi; }

q -q >/dev/null 2>&1 <<'SQL'
set client_min_messages = warning;
set timezone = 'UTC';
-- the pre-#1086 function, as a pre-fix install has it
create or replace function pgpm._canonical_tz(p_tz text)
returns text language sql stable as $f$
  select name from pg_timezone_names where lower(name) = lower(p_tz) order by name limit 1;
$f$;
create table public.ug (ts timestamptz not null, v text);
insert into public.ug values (now() - interval '2 days', 'a'), (now(), 'b');
call pgpm.transmute('public.ug', 'ts', interval '1 day', p_obtain => 2);
select pgpm.set_partition_tz('public.ug', 'localtime');
SQL

[ "$(q -c "select exists (select 1 from pg_timezone_names where name = 'localtime')")" = t ] \
  && say ok "LIVENESS: this server's pg_timezone_names lists localtime" \
  || say no "LIVENESS: this server's pg_timezone_names lists localtime"
[ "$(q -c "select partition_tz from pgpm.config where parent_table = 'public.ug'::regclass")" = localtime ] \
  && say ok "LIVENESS: the pre-fix install recorded localtime as public.ug's grid zone" \
  || say no "LIVENESS: the pre-fix install recorded localtime as public.ug's grid zone"

GUARD_MARK=$(q -c "select coalesce(max(id),0) from pgpm.log")
# the upgrade: the tree's install.sql over the existing install
up=$($PSQL -q --single-transaction -f - < "$TREE/pgpm_core/install.sql" 2>&1); rc=$?
[ "$rc" = 0 ] && say ok "LIVENESS: the upgrade install ran" || { say no "LIVENESS: the upgrade install ran"; echo "$up" | tail -5; }
