[ "$(q -c "select exists (select 1 from pgpm.log where id > $GUARD_MARK and concat_ws(' ', action, method) ilike '%localtime%')")" = t ] && flagged=yes
echo "# after upgrade: partition_tz=$tz flagged=$flagged"
if [ "$tz" != localtime ] || [ "$flagged" = yes ]; then
  say ok "after the upgrade the localtime zone is rewritten or flagged"
else
  say no "after the upgrade public.ug's grid is still recorded in localtime, and neither the install nor a maintenance tick flagged it"
fi
