create extension if not exists dblink;
set client_min_messages = warning;
set timezone = 'UTC';
create or replace function pgpm._canonical_tz(p_tz text)
returns text language sql stable as $f$
  select name from pg_timezone_names where lower(name) = lower(p_tz) order by name limit 1;
$f$;
create table public.rz (id bigint generated by default as identity, ts timestamptz not null default now(),
                        primary key (ts, id));
insert into public.rz (ts) select now() - (g || ' days')::interval from generate_series(1, 20) g;
create table public.v02_out (waited boolean, err_state text, err_msg text);
do $d$
declare v_pid int; waited boolean := false; es text := 'none'; em text := 'the CALL did not fail';
begin
  perform dblink_connect('pw', 'dbname=' || current_database());
  perform dblink_exec('pw', 'begin');
  perform dblink_exec('pw', $$insert into public.rz (ts) values (now() + interval '3 months')$$);
  perform dblink_connect('pa', 'dbname=' || current_database());
  perform dblink_exec('pa', 'set timezone = ''localtime''');
  select pid into v_pid from dblink('pa', 'select pg_backend_pid()') as t(pid int);
  perform dblink_send_query('pa', $$call pgpm.transmute('public.rz', 'ts', interval '1 month', p_obtain => 0)$$);
  for i in 1 .. 400 loop
    if exists (select 1 from pg_locks where pid = v_pid and relation = 'public.rz'::regclass
                  and mode = 'AccessExclusiveLock' and not granted) then waited := true; exit; end if;
    perform pg_sleep(0.01);
  end loop;
  perform dblink_exec('pw', 'commit');
  begin
    perform * from dblink_get_result('pa') as t(r text);
  exception when others then es := sqlstate; em := sqlerrm;
  end;
  perform dblink_disconnect('pa');
  perform dblink_disconnect('pw');
  insert into public.v02_out values (waited, es, em);
end
$d$;
SQL

