out=$(printf "%s\n" "set timezone = 'UTC';" "call pgpm.transmute('public.rz', 'ts', interval '1 month', p_obtain => 0);" | $PSQL -tA 2>&1)
echo "# re-run: $(echo "$out" | head -2)"
resumed=$(q -c "select count(*) from pgpm.log where parent_table = 'public.rz'::regclass and action = 'transmute_resume'")
tz=$(q -c "select partition_tz from pgpm.config where parent_table = 'public.rz'::regclass")
echo "# resumed=$resumed registered partition_tz=${tz:-<none>}"
if [ "$tz" = localtime ]; then
  [ "$resumed" = 1 ] && say ok "LIVENESS: the re-run resumed the pre-fix claim" || say no "LIVENESS: the re-run resumed the pre-fix claim"
  say no "the resumed conversion registered localtime as public.rz's grid zone"
elif [ -n "$tz" ] && [ "$resumed" = 1 ]; then
  say ok "the resumed conversion registered $tz, not localtime"
elif [ -z "$tz" ] && echo "$out" | grep -qi "localtime"; then
  say ok "the re-run refused the claim's localtime zone"
else
  say no "LIVENESS: the re-run reached the resume (it neither resumed nor refused the zone: $out)"
fi
exit $fail
